// Pure geometry shared by the hero puzzle, the skills grid and the puzzle
// divider: which edges are tabs or blanks, the jigsaw outline of each piece,
// where each piece starts before flying in, and the order they arrive. No DOM, no randomness: the server-rendered
// HTML and the client must produce byte-identical output.

export const GRID = { cols: 4, rows: 3, cellW: 120, cellH: 110, knob: 14 }

const round = n => Number(n.toFixed(2))

// +1 = tab (bulges out of this piece), -1 = blank (cut into this piece),
// 0 = straight outer edge. Right/bottom are the "owning" sides; left/top
// mirror the neighbour so adjacent pieces always interlock.
export const edgeSign = (
  row,
  col,
  side,
  cols = GRID.cols,
  rows = GRID.rows
) => {
  switch (side) {
    case "right":
      return col + 1 >= cols ? 0 : (row + col) % 2 === 0 ? 1 : -1
    case "bottom":
      return row + 1 >= rows ? 0 : (row + col) % 2 === 0 ? -1 : 1
    case "left":
      return col === 0 ? 0 : -edgeSign(row, col - 1, "right", cols, rows)
    case "top":
      return row === 0 ? 0 : -edgeSign(row - 1, col, "bottom", cols, rows)
    default:
      throw new Error(`unknown side ${side}`)
  }
}

// One edge from A to B, traversed clockwise, with outward normal n. The
// knob is symmetric about the edge midpoint so the neighbour (opposite
// direction, opposite sign) traces the very same curve.
const edge = (ax, ay, bx, by, nx, ny, s, k) => {
  if (s === 0) return `L${round(bx)} ${round(by)}`
  const L = Math.hypot(bx - ax, by - ay)
  const dx = (bx - ax) / L
  const dy = (by - ay) / L
  const P = (u, v) =>
    `${round(ax + dx * u + nx * s * v)} ${round(ay + dy * u + ny * s * v)}`
  const m = L / 2
  const sweep = s > 0 ? 1 : 0
  return [
    `L${P(m - 0.75 * k, 0)}`,
    `C${P(m - 0.3 * k, 0)} ${P(m - 0.7 * k, 0.5 * k)} ${P(
      m - 0.45 * k,
      0.6 * k
    )}`,
    `A${k} ${k} 0 1 ${sweep} ${P(m + 0.45 * k, 0.6 * k)}`,
    `C${P(m + 0.7 * k, 0.5 * k)} ${P(m + 0.3 * k, 0)} ${P(m + 0.75 * k, 0)}`,
    `L${round(bx)} ${round(by)}`,
  ].join(" ")
}

export const piecePath = ({ row, col, cols, rows, cellW, cellH, knob }) => {
  const x0 = col * cellW
  const y0 = row * cellH
  const x1 = x0 + cellW
  const y1 = y0 + cellH
  const sign = side => edgeSign(row, col, side, cols, rows)
  return [
    `M${round(x0)} ${round(y0)}`,
    edge(x0, y0, x1, y0, 0, -1, sign("top"), knob),
    edge(x1, y0, x1, y1, 1, 0, sign("right"), knob),
    edge(x1, y1, x0, y1, 0, 1, sign("bottom"), knob),
    edge(x0, y1, x0, y0, -1, 0, sign("left"), knob),
    "Z",
  ].join(" ")
}

// Start position of a piece relative to its resting place, spread evenly
// around the mockup with a deterministic pseudo-random distance and spin.
export const scatterOffset = (index, total) => {
  const angle = (index / total) * Math.PI * 2 + 0.6
  // 160.5–259.5 so that rounding dx/dy to 2 dp never leaves the 160–260 band
  const dist = 160.5 + (99 * ((index * 7919) % 1000)) / 999
  const rot = -25 + (50 * ((index * 31) % 100)) / 99
  return {
    dx: round(Math.cos(angle) * dist),
    dy: round(Math.sin(angle) * dist),
    rot: round(rot),
  }
}

// Piece indices sorted by distance from the grid centre, so the mockup
// grows outwards from the middle.
export const pieceOrder = (cols, rows) => {
  const cx = (cols - 1) / 2
  const cy = (rows - 1) / 2
  const dist = i => Math.hypot((i % cols) - cx, Math.floor(i / cols) - cy)
  return [...Array(cols * rows).keys()].sort(
    (a, b) => dist(a) - dist(b) || a - b
  )
}

export const enterDelay = rank => round(rank * 0.07)

export const pieces = (grid = GRID) => {
  const { cols, rows } = grid
  const total = cols * rows
  const order = pieceOrder(cols, rows)
  return [...Array(total).keys()].map(index => {
    const row = Math.floor(index / cols)
    const col = index % cols
    return {
      index,
      row,
      col,
      d: piecePath({ row, col, ...grid }),
      // own centre, in viewBox units: the pivot for the entrance rotation
      ox: round((col + 0.5) * grid.cellW),
      oy: round((row + 0.5) * grid.cellH),
      ...scatterOffset(index, total),
      delay: enterDelay(order.indexOf(index)),
    }
  })
}

// Start offset + entrance delay for skill card `index` of `total`, laid out
// in a cols×rows grid. Reuses scatterOffset (scaled down: the skills column
// is narrower than the hero mockup) and pieceOrder (centre-out). A card the
// grid has no rank for (a ninth skill) takes its own index as rank.
export const skillScatter = (
  index,
  total,
  { cols = 4, rows = 2, scale = 0.6 } = {}
) => {
  const { dx, dy, rot } = scatterOffset(index, total)
  const rank = pieceOrder(cols, rows).indexOf(index)
  return {
    x: round(dx * scale),
    y: round(dy * scale),
    rotate: rot,
    delay: enterDelay(rank === -1 ? index : rank),
  }
}

// Open path for a section divider: a horizontal rule across `width` with one
// knob (tab, bulging upward) centred on it. Baseline at height − 6 so the
// knob's true 2.49·knob protrusion stays inside the box.
export const dividerPath = ({ width = 56, height = 40, knob = 12 } = {}) => {
  const y = height - 6
  return `M0 ${y} ${edge(0, y, width, y, 0, -1, 1, knob)}`
}

// --- Interactive mode -------------------------------------------------------

// A dropped piece snaps home when its offset is within this many viewBox units.
export const SNAP_RADIUS = 18

export const isHome = ({ x, y }, radius = SNAP_RADIUS) =>
  Math.hypot(x, y) <= radius

// Deterministic 0..1 hash so every "shuffle" click (seed) gives a new but
// reproducible layout without Math.random.
const unit = (seed, i, salt) => {
  const n = Math.sin(seed * 9301 + i * 49297 + salt * 233) * 43758.5453
  return n - Math.floor(n)
}

// Offsets (relative to each piece's home) for a shuffled board: a cyclic
// shift of the cells so no piece sits on its own cell, plus ±16 jitter,
// clamped so every piece stays inside the viewBox. No rotation: the
// board stays solvable by eye.
export const shuffleLayout = (seed, grid = GRID) => {
  const { cols, rows, cellW, cellH } = grid
  const total = cols * rows
  const W = cols * cellW
  const H = rows * cellH
  const shift = 1 + (Math.abs(Math.floor(seed)) % (total - 1))
  return [...Array(total).keys()].map(i => {
    const target = (i + shift) % total
    const homeX = (i % cols) * cellW
    const homeY = Math.floor(i / cols) * cellH
    let tx = (target % cols) * cellW + (unit(seed, i, 1) * 2 - 1) * 16
    let ty = Math.floor(target / cols) * cellH + (unit(seed, i, 2) * 2 - 1) * 16
    tx = Math.min(W - cellW, Math.max(0, tx))
    ty = Math.min(H - cellH, Math.max(0, ty))
    return { x: round(tx - homeX), y: round(ty - homeY) }
  })
}
